请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-007

=== 用户原始指令 (query.txt) ===
整个能打勾那种省电卡数字会变点一下找充电宝能读日程还有红色提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个能打勾那种省电卡数字会变点一下找充电宝能读日程还有红色提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "power": {
      "batteryPercent": {
        "type": "integer",
        "description": "当前电量百分比数值，用于进度环动态变化",
        "sampleValue": 18
      },
      "batteryTotal": {
        "type": "integer",
        "description": "电量百分比总量基准",
        "sampleValue": 100
      },
      "batteryPercentText": {
        "type": "string",
        "description": "当前电量百分比展示文本",
        "sampleValue": "18%"
      },
      "savingEnabled": {
        "type": "boolean",
        "description": "省电模式是否已启用，用于复选框选中态",
        "sampleValue": true
      },
      "modeText": {
        "type": "string",
        "description": "省电模式短标签",
        "sampleValue": "省电"
      },
      "alertText": {
        "type": "string",
        "description": "低电量红色提醒短文本",
        "sampleValue": "低电"
      }
    },
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今天的日历事件列表",
          "sampleValue": [
            {
              "entityId": "calendar-sample-001",
              "title": "晚间会议",
              "dtStart": "18:30",
              "dtEnd": "19:00"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条日程项",
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符",
                "sampleValue": "calendar-sample-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题",
                "sampleValue": "晚间会议"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间展示文本",
                "sampleValue": "18:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间展示文本",
                "sampleValue": "19:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_save_power.png",
      "description": "省电模式图标，适合用于低电模式卡片的状态识别。"
    }
  ]
}

